-- ============================================================================
-- Course guides: inline the files/README steps students never get, and fix Builder 1 code bugs (2026-09-26)
--
-- Students only see the guide page; the repo's starter projects (README.md,
-- .env.example, sample files) are not handed out. Guides that pointed at them:
--   * #5 read an "included" sample_transcript.txt: now a step to create it.
--   * #12 had students open five "included" files in sample_data/: now a
--     make_samples.py step writes them (byte-identical to the starter files).
--   * #8 offered an "included" sample.txt: now suggests a web page URL.
--   * #6, #7, #8 said "copy .env.example": now say what to put in .env.
--   * #3 sent students to README.md for the Slack .env values and the
--     cron / Task Scheduler setup: both are now in the guide itself.
--   * #10 and #11 code comments/messages pointed at README sections.
--   * #6 deploy step assumed a requirements.txt nobody told students to make.
--   * #10 troubleshooting still promised a "free always-on host".
--
-- Code bugs (each file re-run against its own self-test, plus new checks):
--   * #2 app.py: an AIError (busy/rate-limited Gemini) became a 500, so the
--     sender got no reply at all. Now sends a fallback reply; new test.
--   * #3 slack_client.py fetched 24 DAYS of history (hours * SECONDS_PER_DAY).
--   * #3 summarizer.py cut the prompt with [:MAX_CHARACTERS], which kept the
--     oldest messages and dropped the newest - the ones the briefing is for.
--     Now trims the oldest lines, with an equal share per channel.
--   * #10 main.py reported every target as a "new product" on the first run,
--     and dropped a target that failed to scrape from the saved snapshot.
--   * #11 calendar_client.py sent local midnight with a "Z" (UTC) suffix, so
--     "today" was shifted by the UTC offset; main.py did not catch the
--     ValueError plan_day raises for a badly formatted reply.
--   * #2 deploy prompt never asked for the requirements.txt Railway needs.
--
-- 32 guarded edits to course_content rows 2, 3, 5, 6, 7, 8, 10, 11, 12.
-- Each edit checks the current value first (md5 for text, exact match for
-- structured values, absence for new keys, array length + neighbour for
-- inserted steps) and the whole migration aborts, changing nothing, on any
-- mismatch. Section 1 is checksummed so a copy/paste slip also aborts.
-- Long texts with small changes ship as "patch" hunks: each hunk must match
-- exactly once and the patched text must hash to the reviewed new_md5.
-- Backup of the touched rows: public.course_content_backup_20260926_b1_fixes (RLS on, anon and
-- authenticated revoked). Run as ONE transaction (SQL editor, apply_migration,
-- or psql -1); the temp table is ON COMMIT DROP, so a non-transactional run
-- fails before writing anything.
--
-- Rollback (touched rows only):
--   update public.course_content c set session = b.session,
--          troubleshooting = b.troubleshooting, resources = b.resources,
--          updated_at = b.updated_at
--     from public.course_content_backup_20260926_b1_fixes b where b.course_id = c.course_id;
-- ============================================================================

-- 1. The edits, in order. "final" is where each edit's value sits once every
--    later insert has shifted it; the post-check reads it there.
create temp table content_edits (
  ord int primary key, course_id int not null, col text not null check (col in ('session','troubleshooting','resources')),
  path text[] not null, final text[] not null, kind text not null check (kind in ('str','patch','json','add','insert')),
  old_md5 text, old_json text, new_text text not null, new_md5 text
) on commit drop;

insert into content_edits values
