    $n$[["\nfrom reply import generate_reply\n\napp = Flask(__name__)\n", "\nfrom reply import generate_reply\nfrom sdt_ai import AIError\n\napp = Flask(__name__)\n"], ["MAX_HISTORY_TURNS = 6  # 3 back-and-forths of context - enough to feel continuous, bounded so cost can't grow forever\n\n\n@app.route(\"/whatsapp\", methods=[\"POST\"])\n", "MAX_HISTORY_TURNS = 6  # 3 back-and-forths of context - enough to feel continuous, bounded so cost can't grow forever\n\n# Sent when the AI can't answer (the free tier is busy, you've hit its rate\n# limit, or the internet is down), so the person still hears back instead\n# of getting silence.\nFALLBACK_REPLY = \"Sorry, I can't reply properly right now - give me a few minutes and I'll get back to you!\"\n\n\n@app.route(\"/whatsapp\", methods=[\"POST\"])\n"], ["\n    history = CONVERSATION_HISTORY.get(sender, [])\n    reply_text = generate_reply(incoming_message, history=history)\n\n    # Append this turn AFTER generating the reply (not before), so a\n", "\n    history = CONVERSATION_HISTORY.get(sender, [])\n    try:\n        reply_text = generate_reply(incoming_message, history=history)\n    except AIError as problem:\n        # Without this, Flask answers Twilio with a 500 error and the\n        # sender gets no reply at all. Print the real reason for you,\n        # send them the fallback, and leave history alone - this turn\n        # never really happened.\n        print(f\"AI error, sent the fallback reply instead: {problem}\")\n        return _twiml_response(FALLBACK_REPLY)\n\n    # Append this turn AFTER generating the reply (not before), so a\n"]]$n$, '4d4a8b412c3f5c094a451c61cc2e95a2'),
  (21, 2, 'session', '{builds,2,steps,1,prompt}', '{builds,2,steps,1,prompt}', 'patch', '6246ace20900bca03b2ea2ffdabb0aa3', null,
    $n$[["\n\nif __name__ == \"__main__\":\n    test_whatsapp_webhook_returns_valid_twiml()\n    test_empty_message_never_reaches_the_ai()\n", "\n\ndef test_ai_failure_still_sends_a_reply():\n    \"\"\"\n    When Gemini is busy or unreachable, ask_ai raises AIError. The webhook\n    must still answer Twilio with valid TwiML (the fallback message), not\n    crash with a 500 that leaves the sender with no reply at all.\n    \"\"\"\n\n    def _ai_is_down(*args, **kwargs):\n        raise app_module.AIError(\"Gemini is busy (test)\")\n\n    original_ask_ai = reply_module.ask_ai\n    reply_module.ask_ai = _ai_is_down\n    try:\n        client = app_module.app.test_client()\n        response = client.post(\"/whatsapp\", data={\"Body\": \"Hello?\", \"From\": \"whatsapp:+15550000000\"})\n        body = response.get_data(as_text=True)\n        assert response.status_code == 200\n        assert \"<Message>\" in body and \"get back to you\" in body\n        assert \"whatsapp:+15550000000\" not in app_module.CONVERSATION_HISTORY\n        print(\"\\nResponse when the AI is down:\")\n        print(body)\n        print(\"PASS: an AI failure still sends the fallback reply.\")\n    finally:\n        reply_module.ask_ai = original_ask_ai\n\n\nif __name__ == \"__main__\":\n    test_whatsapp_webhook_returns_valid_twiml()\n    test_empty_message_never_reaches_the_ai()\n    test_ai_failure_still_sends_a_reply()\n"]]$n$, 'b2bb1eb93f872bca199510f719d3dc2a'),
  (22, 2, 'session', '{builds,2,steps,1,verify}', '{builds,2,steps,1,verify}', 'str', '6bda7291ede98790849b069319d65ffd', null,
