    $n$[["\n# Slack timestamps (\"ts\") are UNIX seconds as a string, e.g. \"1699999999.000100\".\nSECONDS_PER_DAY = 24 * 60 * 60\n\n\n", "\n# Slack timestamps (\"ts\") are UNIX seconds as a string, e.g. \"1699999999.000100\".\nSECONDS_PER_HOUR = 60 * 60\n\n\n"], ["    that's where the logic actually worth testing lives.\n    \"\"\"\n    oldest = str(time.time() - hours * SECONDS_PER_DAY)\n    messages = []\n    cursor = None\n", "    that's where the logic actually worth testing lives.\n    \"\"\"\n    oldest = str(time.time() - hours * SECONDS_PER_HOUR)\n    messages = []\n    cursor = None\n"]]$n$, '3d7a8b85ee24465f66c32b1961f0aeb9'),
  (26, 3, 'session', '{builds,1,steps,2,prompt}', '{builds,1,steps,2,prompt}', 'patch', '38cfd13f07821559afc672cca294c2f6', null,
    $n$[["\n\ndef build_prompt(channel_texts):\n    \"\"\"\n", "\n\ndef _keep_latest(channel_text, budget):\n    \"\"\"\n    Trims one channel's text to about `budget` characters by dropping its\n    OLDEST lines. Messages arrive oldest-first, so the newest ones - the\n    overnight messages most likely to need attention this morning - are\n    at the end, and they're the ones worth keeping. Cutting from the end\n    instead would throw away exactly what the briefing is for.\n    \"\"\"\n    if len(channel_text) <= budget:\n        return channel_text\n\n    header, _, body = channel_text.partition(\"\\n\")\n    marker = \"[...older messages trimmed]\"\n    room = budget - len(header) - len(marker) - 2\n    kept = []\n    for line in reversed(body.splitlines()):\n        if len(line) + 1 > room:\n            break\n        kept.append(line)\n        room -= len(line) + 1\n    if not kept:\n        # A single message longer than the whole budget - keep its end.\n        kept = [body[len(body) - max(room, 0):]]\n    kept.reverse()\n    return header + \"\\n\" + marker + \"\\n\" + \"\\n\".join(kept)\n\n\ndef build_prompt(channel_texts):\n    \"\"\"\n"], ["    slack_client.filter_and_format_messages() as \"--- #channel ---\\\\n...\".\n    \"\"\"\n    combined = \"\\n\\n\".join(channel_texts)[:MAX_CHARACTERS]\n\n    return f\"\"\"You are preparing a morning briefing for someone who was away from\n", "    slack_client.filter_and_format_messages() as \"--- #channel ---\\\\n...\".\n    \"\"\"\n    # Each channel gets an equal share of MAX_CHARACTERS, so one very loud\n    # channel can't push the others out of the briefing entirely.\n    budget = MAX_CHARACTERS // max(len(channel_texts), 1)\n    combined = \"\\n\\n\".join(_keep_latest(text, budget) for text in channel_texts)\n\n    return f\"\"\"You are preparing a morning briefing for someone who was away from\n"], ["    assert len(huge_prompt) < len(huge_input[0]) + 2000, \"MAX_CHARACTERS should have capped this\"\n\n    print(\"\\nAll summarizer.py self-tests passed.\")\n", "    assert len(huge_prompt) < len(huge_input[0]) + 2000, \"MAX_CHARACTERS should have capped this\"\n\n    # ...and what gets cut is the OLDEST chatter, never the newest, while a\n    # second, quieter channel still makes it into the prompt.\n    loud = \"--- #general ---\\n\" + \"\\n\".join(f\"U1: message {i}\" for i in range(2000))\n    quiet = \"--- #eng-team ---\\nU2: deploy is blocked, need a decision today\"\n    trimmed_prompt = build_prompt([loud, quiet])\n    assert \"U1: message 1999\" in trimmed_prompt, \"the newest message should survive trimming\"\n    assert \"U1: message 0\\n\" not in trimmed_prompt, \"the oldest messages should be the ones trimmed\"\n    assert \"deploy is blocked\" in trimmed_prompt, \"a quiet channel must not be crowded out\"\n\n    print(\"\\nAll summarizer.py self-tests passed.\")\n"]]$n$, '38b8b35ebc036ae0cf96cc388d28c2c2'),
  (27, 3, 'session', '{builds,1,steps,2,verify}', '{builds,1,steps,2,verify}', 'str', 'deee9db4163d081acb01285ecd8e526f', null,
    $n$Run `python summarizer.py`. It checks the parser against a well-formed reply, a malformed reply with no markers at all, and an oversized input that should get trimmed to MAX_CHARACTERS by dropping the oldest messages (never the newest, and never a whole quieter channel) - all without spending any Gemini credits. You should see "All summarizer.py self-tests passed." at the end.$n$, null),
  (28, 10, 'session', '{builds,3,steps,0,prompt}', '{builds,3,steps,0,prompt}', 'patch', '6d023c2bcf6d33091459e8d99cd1593c', null,
    $n$[["    current = {}\n    scrape_errors = []\n\n    for entry in TARGETS:\n", "    current = {}\n    scrape_errors = []\n    failed_targets = []\n\n    for entry in TARGETS:\n"], ["            # checking every other target, and just report this one.\n            scrape_errors.append(f\"{entry['target']}: {problem}\")\n\n    for problem in scrape_errors:\n        print(f\"Skipped a target: {problem}\")\n\n    changes = diff_snapshots(previous, current)\n", "            # checking every other target, and just report this one.\n            scrape_errors.append(f\"{entry['target']}: {problem}\")\n            failed_targets.append(entry[\"target\"])\n\n    for problem in scrape_errors:\n        print(f\"Skipped a target: {problem}\")\n\n    if not previous:\n        # Very first run: there's nothing to compare against yet, and\n        # diffing against an empty snapshot would report every target as\n        # a \"new product\". Just save today's scrape as the starting point.\n        save_snapshot(SNAPSHOT_FILE, current)\n        print(f\"First run: saved a snapshot of {len(current)} target(s) to compare against next time.\")\n        return\n\n    changes = diff_snapshots(previous, current)\n"], ["    # against the same stale snapshot forever, which is a subtler\n    # version of the \"alert every run\" bug in the troubleshooting notes.\n    save_snapshot(SNAPSHOT_FILE, current)\n\n", "    # against the same stale snapshot forever, which is a subtler\n    # version of the \"alert every run\" bug in the troubleshooting notes.\n    #\n    # A target that failed to scrape this time keeps its last known data\n    # in the file. Dropping it would make the next successful scrape look\n    # like a brand-new product, and a target that keeps failing would be\n    # reported missing once and then silently forgotten.\n    for target_name in failed_targets:\n        if target_name in previous:\n            current[target_name] = previous[target_name]\n    save_snapshot(SNAPSHOT_FILE, current)\n\n"], ["    # A schedule on your own laptop only fires while the laptop is on\n    # and awake -- it silently stops the moment it sleeps or shuts down.\n    # For real always-on monitoring, deploy this the same way as the\n    # WhatsApp/Gmail course guides (a free always-on host).", "    # A schedule on your own laptop only fires while the laptop is on\n    # and awake -- it silently stops the moment it sleeps or shuts down.\n    # For real always-on monitoring, deploy it to an always-on host such\n    # as Railway or Render (check their current plans - neither keeps a\n    # job running 24/7 for free)."]]$n$, 'c159496d4f930c15178d8e86db384f86'),
  (29, 10, 'session', '{builds,3,steps,0,verify}', '{builds,3,steps,0,verify}', 'str', 'be482d0170b13e5507e438b6a45c9803', null,
